select
  studyid, checkdate, resultdate, deptname, xxdm, xxmc, result, nvalue, cvalue, mvalue, doctor, deptcode, doctordm
from view_jcb

    
        and studyid = #{studyid}
    
    
        and checkdate = #{checkdate}
    
    
        and resultdate = #{resultdate}
    
    
        and deptname = #{deptname}
    
    
        and xxdm = #{xxdm}
    
    
        and xxmc = #{xxmc}
    
    
        and result = #{result}
    
    
        and nvalue = #{nvalue}
    
    
        and cvalue = #{cvalue}
    
    
        and mvalue = #{mvalue}
    
    
        and doctor = #{doctor}
    
    
        and deptcode = #{deptcode}
    
    
        and doctordm = #{doctordm}
    

limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from view_jcb

    
        and studyid = #{studyid}
    
    
        and checkdate = #{checkdate}
    
    
        and resultdate = #{resultdate}
    
    
        and deptname = #{deptname}
    
    
        and xxdm = #{xxdm}
    
    
        and xxmc = #{xxmc}
    
    
        and result = #{result}
    
    
        and nvalue = #{nvalue}
    
    
        and cvalue = #{cvalue}
    
    
        and mvalue = #{mvalue}
    
    
        and doctor = #{doctor}
    
    
        and deptcode = #{deptcode}
    
    
        and doctordm = #{doctordm}

        select count(*)
        from 检查类结果
        
            
                and StudyID = #{studyid}
            
            
                and date_format(结论日期,'%Y-%m-%d') = #{params.recordingDate}

select
预约id studyid,检查日期 checkdate,结论日期 resultdate,科室 deptname,细项代码 xxdm,细项名称 xxmc,检查结果 result, nvalue, cvalue, mvalue,检查医生 doctor, deptcode, doctordm
from 检查类结果

    
        and StudyID = #{jcb.studyid}
    
    
        and date_format(结论日期,'%Y-%m-%d') = #{jcb.params.recordingDate}
    

order by 结论日期
limit #{pageable.offset}, #{pageable.pageSize}
